import corridor from '../../../data/corridors/bloor-christie-ossington.json'
import type { Corridor, ElementId, Level } from '../model/types'

// Level 1 on real Toronto data (#11). The corridor JSON is generated by data/prep (prep.py corridor).
export const BLOOR_LEVEL: Level = {
  id: corridor.id,
  name: corridor.name,
  corridor: { ...corridor, baselineLayout: { elements: corridor.baselineLayout.elements.map((e) => ({ ...e, id: e.id as ElementId })) } } as Corridor,
  allowedElements: ['sidewalk', 'car_lane', 'bus_lane', 'bike_painted', 'bike_protected', 'parking', 'planter'],
  // Tuned on the model (PR #11): every one-car-lane design reaches the 33.9% shift-capped cut, so the stars
  // turn on safety (a buffer between traffic and people) and fairness (keeping curb access for everyone).
  goal: { minEmissionsReductionPct: 25, minHappiness: 50 },
  stars: { safety: 59, fairness: 60 },
}
